/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: AlbumPage
 * Internal
 *   Constants: creditRoleKeys
 * @end-catalog */

import { useMemo, useRef, type CSSProperties } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Link, useParams } from 'react-router';

import type { LibraryTarget } from '../../api/contentSchemas';
import { listenerAlbumQuery, saveStatusesQuery } from '../../api/listener';
import { contentByline } from '../../api/contentSchemas';
import { browserSessionQuery } from '../../api/session';
import { neutralArtworkTone, useArtworkTone } from '../../artwork/useArtworkTone';
import { Artwork } from '../../components/Artwork';
import { LinkedByline } from '../../components/LinkedByline';
import { TrackTable } from '../../components/TrackTable';
import { Icon } from '../../components/Icon';
import { SaveButton } from '../../components/SaveButton';
import { launchAlbumPlayback } from '../playback/launchPlayback';
import { LazyAddTrackToPlaylistButton as AddTrackToPlaylistButton } from '../playlists/LazyAddTrackToPlaylistButton';
import { CompactCatalogHeader } from './CompactCatalogHeader';
import { useFittedHeroTitle } from './useFittedHeroTitle';
import styles from './CatalogPages.module.css';
import { LazyRoomTrackButton } from '../social/LazyRoomTrackButton';
import { useLocalization } from '../../localization/LocalizationProvider';
import type { MessageKey } from '../../localization/contract';
import { playerStore } from '../../player';
import { usePlaybackContext } from '../../player/usePlaybackContext';
import { LazyShareMusicButton } from '../social/LazyShareMusicButton';

const creditRoleKeys: Record<string, MessageKey> = {
  primary: 'catalog.credit.primary',
  featured: 'catalog.credit.featured',
  performer: 'catalog.credit.performer',
  composer: 'catalog.credit.composer',
  producer: 'catalog.credit.producer',
  remixer: 'catalog.credit.remixer',
  label: 'catalog.credit.label',
  publisher: 'catalog.credit.publisher',
  distributor: 'catalog.credit.distributor',
  presenter: 'catalog.credit.presenter',
  legacyUnspecified: 'catalog.credit.credit'
};

/** Renders one expanded Album and launches its canonical ready-only queue. */
export const AlbumPage = () => {
  const { t } = useLocalization();
  const { albumId = '' } = useParams();
  const session = useQuery(browserSessionQuery());
  const viewerId = session.data?.user.id;
  const albumQuery = useQuery(listenerAlbumQuery(albumId));
  const heroRef = useRef<HTMLElement>(null);
  const heroPlayRef = useRef<HTMLButtonElement>(null);
  // The opaque header paints its own tone, so the main pane stays untinted beneath it: a pane
  // gradient taller than a short header would otherwise show as a band below it.
  const tone = useArtworkTone(albumQuery.data?.album.artworkUrl) ?? neutralArtworkTone;
  const title = albumQuery.data?.album.title || t('content.title.untitled_album');
  const titleFit = useFittedHeroTitle(albumQuery.data ? title : null);
  const targets = useMemo<LibraryTarget[]>(() => {
    if (!albumQuery.data) return [];
    return [
      { contentType: 'album', contentId: albumQuery.data.album.id },
      ...albumQuery.data.tracks.map((track) => ({
        contentType: 'audioTrack' as const,
        contentId: track.id
      }))
    ];
  }, [albumQuery.data]);
  const trackIds = useMemo(() => albumQuery.data?.tracks.map((track) => track.id) ?? [], [albumQuery.data]);
  const playback = usePlaybackContext(trackIds);
  const statuses = useQuery(saveStatusesQuery(viewerId ?? '', targets));
  const savedByKey = useMemo(() => new Map(
    statuses.data?.items.map((item) => [`${item.contentType}:${item.contentId}`, item.saved]) ?? []
  ), [statuses.data]);
  const savedFor = (target: LibraryTarget) => {
    if (!viewerId) return false;
    const key = `${target.contentType}:${target.contentId}`;
    return statuses.isError ? null : savedByKey.get(key) ?? null;
  };

  if (albumQuery.isPending) {
    return <div className={styles.page}><div className={styles.state} aria-busy="true">{t('catalog.album.loading')}</div></div>;
  }
  if (albumQuery.isError) {
    return (
      <div className={styles.page}>
        <div className={styles.state} role="alert">
          <h1>{t('catalog.album.unavailable')}</h1>
          <p>{t('catalog.error.copy')}</p>
          <button onClick={() => albumQuery.refetch()} type="button">{t('common.action.try_again')}</button>
        </div>
      </div>
    );
  }

  const { album, tracks } = albumQuery.data;
  const albumTarget: LibraryTarget = { contentType: 'album', contentId: album.id };
  const byline = contentByline(album);
  const play = () => { void launchAlbumPlayback(album.id, tracks, viewerId); };

  return (
    <>
      <CompactCatalogHeader
        heroPlayRef={heroPlayRef}
        heroRef={heroRef}
        onPlay={play}
        playDisabled={tracks.length === 0}
        playLabel={byline
          ? t('content.album.play_byline_label', { title, byline })
          : t('content.album.play_label', { title })}
        title={title}
        tone={tone.pane}
      />
      <div className={`${styles.page} ${styles.albumPage}`}>
        <header className={styles.albumHeroBlock} ref={heroRef} style={{ '--tone-color': tone.hero } as CSSProperties}>
          <div className={styles.hero}>
            <Artwork
              alt={t('content.album.cover_alt', { title: album.title })}
              className={styles.heroArtwork}
              fetchPriority="high"
              kind="album"
              loading="eager"
              sizes="(max-width: 520px) 12rem, (max-width: 720px) 10rem, 20rem"
              src={album.artworkUrl}
            />
            <div className={styles.heroCopy}>
              <p className={styles.eyebrow}>{t('common.label.album')}</p>
              <h1 className={styles.albumTitle} data-title-size={titleFit.initialSize} ref={titleFit.ref} title={title}>{title}</h1>
              <p className={styles.metadata}>
                {[byline, album.releaseDate?.year
                  ? String(album.releaseDate.year)
                  : t('common.label.album'), t('catalog.album.track_count', { count: tracks.length })]
                  .filter(Boolean)
                  .join(' · ')}
              </p>
            </div>
          </div>
          <div className={`${styles.actions} ${styles.albumActions}`}>
            <LazyShareMusicButton contentType="album" contentId={album.id} title={album.title} />
            <button
              aria-label={t('common.action.play')}
              className={styles.playButton}
              disabled={tracks.length === 0}
              onClick={play}
              ref={heroPlayRef}
              type="button"
            >
              <Icon name="play" />
              <span className={styles.playLabel}>{t('common.action.play')}</span>
            </button>
            <SaveButton
              compact
              saved={savedFor(albumTarget)}
              target={albumTarget}
              viewerId={viewerId}
            />
          </div>
        </header>

        {viewerId && statuses.isError && <div className={styles.state} role="alert">
          <p>{t('library.error.load')}</p>
          <button onClick={() => statuses.refetch()} type="button">{t('common.action.try_again')}</button>
        </div>}

        {(album.credits?.length ?? 0) > 0 && (
          <section className={styles.creditSection} aria-labelledby="album-credits-title">
            <div className={styles.sectionHeader}>
              <div>
                <p className={styles.eyebrow}>{t('catalog.album.attribution')}</p>
                <h2 id="album-credits-title">{t('common.label.credits')}</h2>
              </div>
            </div>
            <ul className={styles.creditList}>
              {album.credits?.map((credit) => (
                <li key={`${credit.subjectType}:${credit.subjectId}:${credit.role}`}>
                  <Link to={`/${credit.subjectType === 'artist' ? 'artists' : 'organizations'}/${encodeURIComponent(credit.subjectId)}`}>
                    <span>{credit.name}</span>
                    <small>{t(creditRoleKeys[credit.role] ?? 'catalog.credit.credit')}</small>
                  </Link>
                </li>
              ))}
            </ul>
          </section>
        )}

        <section aria-labelledby="album-soundtracks-title" style={{ '--tt-sticky-top': '4rem' } as CSSProperties}>
          <h2 className="visually-hidden" id="album-soundtracks-title">{t('common.label.mediatracks')}</h2>
          {tracks.length > 0 ? (
            <TrackTable
              durationHeading={t('playlist.detail.table.duration')}
              rows={tracks.map((track) => {
                const target: LibraryTarget = { contentType: 'audioTrack', contentId: track.id };
                const title = track.title || t('content.title.untitled_track');
                const state = track.id === playback.currentId ? playback.status : null;
                const trackByline = contentByline(track);
                return {
                  key: track.id,
                  title,
                  // A row never repeats the Album title; it falls back to the Album byline.
                  byline: trackByline
                    ? <LinkedByline credits={track.credits} text={trackByline} />
                    : byline && <LinkedByline credits={album.credits} text={byline} />,
                  duration: track.duration,
                  state,
                  playLabel: state === 'playing' ? t('player.action.pause') : t('content.play.label', { title }),
                  onActivate: () => {
                    if (state === 'playing') playerStore.pause();
                    else if (state === 'paused' && playback.matches) void playerStore.play();
                    else void launchAlbumPlayback(album.id, tracks, viewerId, track.id);
                  },
                  actions: <>
                    {track.mediaType !== 'video' && <LazyRoomTrackButton mediaTrackId={track.id} title={title} />}
                    <LazyShareMusicButton contentType="audioTrack" contentId={track.id} title={title} />
                    <AddTrackToPlaylistButton
                      accountPending={session.isPending}
                      accountUnavailable={session.isError}
                      track={track}
                      viewerId={viewerId}
                    />
                  </>,
                  save: <SaveButton compact saved={savedFor(target)} target={target} viewerId={viewerId} />
                };
              })}
              titleHeading={t('playlist.detail.table.title')}
              variant="album"
            />
          ) : (
            <div className={styles.empty}>{t('catalog.album.empty')}</div>
          )}
        </section>
      </div>
    </>
  );
};
